From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition compiler_pass_text : string := "".
Definition compiler_pass_nodes :=
 match Wire.decode_text compiler_pass_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition compiler_pass_decode := match compiler_pass_nodes with
 | Some xs => definitions 500 (firstn 1 xs) | None => None end.
Definition compiler_pass_program := Eval vm_compute in
 match compiler_pass_decode with Some ds => ds | None => [] end.
Theorem compiler_pass_exact : compiler_pass_decode = Some compiler_pass_program.
Proof. vm_compute. reflexivity. Qed.
Theorem compiler_pass_names : map fst compiler_pass_program = ["kl:_scm.merge-nested-lets"].
Proof. vm_compute. reflexivity. Qed.
Global Opaque compiler_pass_text compiler_pass_nodes compiler_pass_decode.
